import json,copy,hashlib
from pathlib import Path
from datetime import datetime,timezone
HERE=Path(__file__).resolve().parent
src=HERE.parent/'workshop-2026'/'valve-inspection-v1.procedure.json'
base=json.loads(src.read_text(encoding='utf-8-sig'))
url=base['source']['source_url']
p={k:copy.deepcopy(base[k]) for k in ['schema_version','target','scope_confirmed','status','publication_status','source','required_tools']}
p.update(id='yamaha-2026-yz450f-airbox-remove-refit-v1',title='Remove and refit the stock airbox',completeness='Complete assembled-bike tank/body access, intact air-filter-case removal, intake joint refit and body/fuel closure. The filter, intake-temperature sensor and case assembly bracket remain attached to the case. Throttle body, cables and calibration remain untouched.',applicability={'included':'Exact stock US2026 YZ450F air-filter-case, mounts, intake joint and fuel tank','excluded':['Other years/models','Aftermarket airbox or intake','Filter cleaning or replacement','Throttle-body or throttle-cable removal','TPS/idle calibration'],'year_inheritance':'NONE'},required_parts=[],preflight=['Engine stopped and cool; stable support; clean intake/fuel work area.','Intact clean filter, sound stock case/joint/seals and mounting hardware.','Fuel-safe tank-removal equipment and joint covers available.'],critical_stop_conditions=['Intake joint damaged, contaminated or cannot seat fully.','A mounting collar, damper or sealing interface is unaccounted for.','Fuel leak, unlatched connector or pinched hose/wire after refit.'],derivation={'source_artifact':'../workshop-2026/valve-inspection-v1.procedure.json','sha256':hashlib.sha256(src.read_bytes()).hexdigest(),'method':'Reuses only reviewed tank/body access and closure; no valve-work steps.'},steps=copy.deepcopy(base['steps'][:6]))
p['required_tools']=[x for x in p['required_tools'] if x['name'] in ['Fuel-safe transfer pump, approved container, absorbent cloths, included fuel-hose joint covers','Stable bike support, clean parts trays and measurement log']]+[{'name':'Appropriate tank/body/airbox tools and calibrated low-range torque wrench','range':'3–13 N·m'}]
p['steps'][0]['instruction']='Stop the engine, let it cool and support the bike. Clean the intake and fuel work area. Keep dirt out of open joints and fuel work away from ignition sources.'
def step(id,title,text,pages,verify,record=False):
 return {'id':id,'title':title,'instruction':text,'source_pdf_pages':pages,'verification':[verify],'diagram_reference_required':True,'source_links':[url+'#page='+str(n) for n in pages],'record_required':record,'depends_on':[],'origin':'Original source-based bounded summary; part logging and clean-joint protection are workflow adaptations.'}
p['steps'] += [step('case-release','Release the intact case','Disconnect the intake-air-temperature-sensor coupler by its connector latch. Loosen the air-filter-case joint clamp screw and remove the three case mounting bolts, retaining their collars, washers and dampers at the original locations. Keep the filter, temperature sensor and case assembly bracket attached to the case.',[57,309,310],'Sensor coupler disconnected; three mounting sets retained; case internals attached.'),step('case-remove','Lift off and protect the intake','Lift the case clear of its seated intake connection without loading the remaining throttle body. Protect the exposed throttle-body inlet from dirt. Keep the case clean and inspect the joint and mounting supports for visible damage. Do not push the throttle valve, loosen sensor screws or move the cables.',[309,310,312],'Intact case removed; clean inlet protected; throttle and sensors undisturbed.'),step('case-refit','Seat the case and secure its mounts','Remove the temporary inlet protection and seat the complete case fully on the throttle-body intake connection in its original orientation. Restore the original mounting collars, dampers and washers. Tighten the three case mounting bolts to7 N·m and the air-filter-case joint clamp screw to3 N·m. Confirm the joint lip is evenly seated and not folded. Reconnect the temperature-sensor coupler until its latch engages.',[57,309,310],'Three mounts7 N·m; joint clamp3 N·m; joint fully seated; sensor connector latched.',True),step('intake-check','Verify the restored intake','Check case support, full joint seating, wiring clearance and that all temporary intake protection has been removed. The filter and bracket stayed assembled; if either has moved or a seal cannot be accounted for, resolve it before closing the bike.',[309,310,313,314],'Intake complete and clean; retained assembly bracket/element secure.',True)]
p['steps']+=copy.deepcopy([s for s in base['steps'] if s['id'] in ['tank-install','body-install','closeout']])
p['steps'][-1]['instruction']='Restore fuel safely and secure the tank cap. Account for the joint covers, intake protection, tools and removed hardware. Check fuel joints for leakage and verify no hose or wire is trapped. Save the case removal/refit and hardware checks; this does not claim filter cleaning, throttle calibration or engine service.'
for i,s in enumerate(p['steps']):
 s['depends_on']=[] if i==0 else [p['steps'][i-1]['id']]
 s.setdefault('record_required',s['id']=='closeout')
p['source']['pdf_pages']=sorted({n for s in p['steps'] for n in s['source_pdf_pages']})
p['source']['printed_pages']=['2-10','4-1 to4-5','7-1 to7-5','7-7 to7-9']
p['source']['review_note']='PDF309310312313314 visually reviewed this pass with exact clamp/mount mapping reconciled against previously reviewed PDF57. Existing source-reviewed tank/body access and closure retained. Intact-case adaptation does not remove filter, sensor or clipped assembly bracket.'
p['reviewed_at']=datetime.now(timezone.utc).isoformat()
(HERE/'airbox-remove-refit-v1.procedure.json').write_text(json.dumps(p,indent=2)+'\n',encoding='utf-8')
print('Saved complete',len(p['steps']),'step airbox removal/refit.')
